content:
} else if (tkl == COAP_TOKEN_EXT_2B_TKL) {
        size += ((uint16_t)token_start[0] << 8) + token_start[1] +
                COAP_TOKEN_EXT_2B_BIAS + 2;
      } else {
        /* Invalid at this point - caught later as undersized */
      }
    }
  }

  return size;
}
