static int
coap_pdu_parse_opt_base(coap_pdu_t *pdu, uint16_t len) {
  int res = 1;

  switch (pdu->max_opt) {
  case COAP_OPTION_IF_MATCH:
    if (len > 8)
      res = 0;
    break;
  case COAP_OPTION_URI_HOST:
    if (len < 1 || len > 255)
      res = 0;
    break;
  case COAP_OPTION_ETAG:
